60	// Ensure that the output takes up the available width of the terminal.
61	yargs.wrap(yargs.terminalWidth());
62	
63	export const parserConfiguration: Partial<yargs.ParserConfigurationOptions> = {
64	  'strip-dashed': true,
65	};
66	
67	/**
68	 * Exposing the Yargs commands object so the documentation generator can
69	 * parse it. The CLI will consume it and call the `.argv` to bootstrapped
70	 * the CLI. These command declarations needs to be in a different file
71	 * from the `.argv` call, so the object and it's relative scripts can
72	 * be executed correctly.
73	 */
74	export const commandsObject = yargs
75	  .parserConfiguration(parserConfiguration)
76	  .usage(pc.bold('Smart Monorepos · Fast Builds'))
77	  .demandCommand(1, '')
78	  .command(yargsRegisterCommand)
79	  .command(yargsAddCommand)
80	  .command(yargsConfigureAiAgentsCommand)
81	  .command(yargsAffectedBuildCommand)
82	  .command(yargsAffectedCommand)
83	  .command(yargsAffectedE2ECommand)
84	  .command(yargsAffectedLintCommand)
85	  .command(yargsAffectedTestCommand)
86	  .command(yargsAffectedGraphCommand)
87	  .command(yargsConnectCommand)
88	  .command(yargsDaemonCommand)
89	  .command(yargsGraphCommand)
90	  .command(yargsExecCommand)
91	  .command(yargsFormatCheckCommand)
92	  .command(yargsFormatWriteCommand)
93	  .command(yargsGenerateCommand)
94	  .command(yargsImportCommand)
95	  .command(yargsInitCommand)
96	  .command(yargsInternalMigrateCommand)
97	  .command(yargsListCommand)
98	  .command(yargsMigrateCommand)
99	  .command(yargsNewCommand)
100	  .command(yargsPrintAffectedCommand)
101	  .command(yargsReleaseCommand)
102	  .command(yargsRepairCommand)
103	  .command(yargsReportCommand)
104	  .command(yargsResetCommand)
105	  .command(yargsRunCommand)
106	  .command(yargsRunManyCommand)
107	  .command(yargsShowCommand)
108	  .command(yargsSyncCommand)
109	  .command(yargsSyncCheckCommand)
110	  .command(yargsViewLogsCommand)
111	  .command(yargsWatchCommand)
112	  .command(yargsNxInfixCommand)
113	  .command(yargsLoginCommand)
114	  .command(yargsLogoutCommand)
115	  .command(yargsRecordCommand)
116	  .command(yargsStartCiRunCommand)
117	  .command(yargsStartAgentCommand)
118	  .command(yargsStopAllAgentsCommand)
119	  .command(yargsFixCiCommand)
120	  .command(yargsApplyLocallyCommand)
121	  .command(yargsDownloadCloudClientCommand)
122	  .command(yargsMcpCommand)
123	  .command(resolveConformanceCommandObject())
124	  .command(resolveConformanceCheckCommandObject())
125	  .scriptName('nx')
126	  .middleware((args) => {
127	    const context = (commandsObject as any).getInternalMethods().getContext();
128	    const command =
129	      (context.commands ?? []).join(' ') ||
130	      (args._ ?? []).slice(0, 1).join(' ');
131	    if (command) {
132	      reportCommandRunEvent(command, undefined, args);
133	    }
134	  })
135	  .help(false)
136	  // NOTE: we handle --version in nx.ts, this just tells yargs that the option exists
137	  // so that it shows up in help. The default yargs implementation of --version is not
138	  // hit, as the implementation in nx.ts is hit first and calls process.exit(0).
139	  .version();
140	
141	function createMissingConformanceCommand(
142	  command: 'conformance' | 'conformance:check'
143	) {
144	  return {
145	    command,
146	    // Hide from --help output in the common case of not having the plugin installed
147	    describe: false,
148	    handler: () => {
149	      output.error({
150	        title: `${command} is not available`,
151	        bodyLines: [
152	          `In order to use the \`nx ${command}\` command you must have an active Nx key and the \`@nx/conformance\` plugin installed.`,
153	          '',
154	          'To learn more, visit https://nx.dev/nx-enterprise/powerpack/conformance',
155	        ],
156	      });
157	      process.exit(1);
158	    },
159	  };
160	}
161	
162	function resolveConformanceCommandObject() {
163	  try {
164	    const { yargsConformanceCommand } = (() => {
165	      try {
166	        return require('@nx/powerpack-conformance');
167	      } catch {
168	        return require('@nx/conformance');
169	      }
170	    })();
171	    return yargsConformanceCommand;
172	  } catch {
173	    return createMissingConformanceCommand('conformance');
174	  }
175	}
176	
177	function resolveConformanceCheckCommandObject() {
178	  try {
179	    const { yargsConformanceCheckCommand } = (() => {
180	      try {
181	        return require('@nx/powerpack-conformance');
182	      } catch {
183	        return require('@nx/conformance');
184	      }
185	    })();
186	    return yargsConformanceCheckCommand;
187	  } catch {
188	    return createMissingConformanceCommand('conformance:check');
189	  }
190	}
