7	export const yargsWatchCommand: CommandModule = {
8	  command: 'watch',
9	  describe: 'Watch for changes within projects, and execute commands.',
10	  builder: (yargs) => linkToNxDevAndExamples(withWatchOptions(yargs), 'watch'),
11	  handler: async (args) => {
12	    await handleImport('./watch.js', __dirname).then((m) =>
13	      m.watch(args as WatchArguments)
14	    );
15	  },
16	};
17	
18	function withWatchOptions(yargs: Argv) {
19	  return (
20	    withVerbose(yargs)
21	      .parserConfiguration({
22	        'strip-dashed': true,
23	        'populate--': true,
24	      })
25	      .option('projects', {
26	        type: 'string',
27	        alias: 'p',
28	        coerce: parseCSV,
29	        description: 'Projects to watch (comma/space delimited).',
30	      })
31	      .option('all', {
32	        type: 'boolean',
33	        description: 'Watch all projects.',
