 * Parses a `process.argv`-style array for shell completion.
 *
 * The array is expected to look like `[node, /path/to/nx, ...userTokens]`.
 * We strip the first two entries (the node runtime and the nx binary path),
 * then strip a leading `nx` script-name token if the completion script passed
 * it along. The remaining entries are the shell tokens the user has typed so
 * far, where the final token is the (possibly empty) partial being completed.
 */
export function parseCompletionArgs(
  argv: string[]
): { tokens: string[]; current: string; previousToken: string } | null {
  // Strip the node runtime and the nx binary path.
  let tokens = argv.slice(2);

  // Strip a leading `nx` script-name token if present.
  if (tokens[0] === 'nx') {
    tokens = tokens.slice(1);
  }

  if (tokens.length === 0) {
    return null;
  }

  const current = tokens[tokens.length - 1];
  const previousToken = tokens.length > 1 ? tokens[tokens.length - 2] : '';

  return { tokens, current, previousToken };
}
