 * The separator between a completion value and its description.
 *
 * This is intentionally a TAB character rather than a colon: completion values
 * and command names may themselves contain colons (e.g. `my-app:build`), so a
 * colon cannot reliably split a value from its description.
 */
export const DESC_SEPARATOR = '\t';

const YARGS_STRING_PREFIX = '__yargsString__:';

/**
 * Sanitizes a command description for use in shell completion output.
 *
 * - Strips the yargs i18n marker prefix `__yargsString__:` from the start.
 * - Collapses any literal TAB characters in the remainder to spaces so they
 *   don't break the value/description split that shells perform on TAB.
 * - Returns `''` for undefined or empty input.
 *
 * Colons that appear within the description are left untouched.
 */
export function formatDescription(description: string | undefined): string {
  if (!description) {
    return '';
  }

  let result = description;
  if (result.startsWith(YARGS_STRING_PREFIX)) {
    result = result.slice(YARGS_STRING_PREFIX.length);
  }

  return result.replace(/\t/g, ' ');
}

/**
 * Returns true when the current shell (determined by the `NX_COMPLETE`
 * environment variable) renders completion descriptions alongside values.
 * Only `zsh` and `fish` do; `bash`, `powershell`, `nushell`, or an unset
 * `NX_COMPLETE` return false.
 */
export function shellRendersDescriptions(): boolean {
  const shell = process.env.NX_COMPLETE;
  return shell === 'zsh' || shell === 'fish';
}
