 * non-flag tokens typed beyond the matched path, excluding the final (current)
 * token being completed. Returns null when no path matches.
 */
export function findCompletionMetadata(
  tokens: string[]
): { metadata: CompletionMetadata; positionalIndex: number } | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  let bestMetadata: CompletionMetadata | null = null;
  let bestLength = -1;

  for (const [path, metadata] of registry) {
    const parts = path.split(' ');
    if (parts.length > tokens.length) {
      continue;
    }

    let matches = true;
    for (let i = 0; i < parts.length; i++) {
      // A flag anywhere in the path region halts the walk — it can never be
      // part of a command path.
      if (isFlag(tokens[i]) || tokens[i] !== parts[i]) {
        matches = false;
        break;
      }
    }

    if (matches && parts.length > bestLength) {
      bestMetadata = metadata;
      bestLength = parts.length;
    }
  }

  if (!bestMetadata) {
    return null;
  }

  // The final token is the partial being completed and must not count toward
  // the positional index. Everything between the matched path and that final
  // token that is not a flag is a completed positional.
  const beyondPath = tokens.slice(bestLength, tokens.length - 1);
  const positionalIndex = beyondPath.filter((t) => !isFlag(t)).length;

  return { metadata: bestMetadata, positionalIndex };
