 * Flag dispatch takes precedence: if `previousToken` starts with `--` and a
 * handler is registered, the handler is called with `(current, tokens)`. If
 * `previousToken` starts with `--` but no handler exists, [] is returned (no
 * fallthrough to positionals). Otherwise the positional completer at the
 * computed positionalIndex is used (a `complete` function or `choices`
 * filtered by prefix). Returns null for empty tokens, no metadata match, or a
 * positionalIndex beyond the declared positionals.
 */
export function resolveCompletion(
  tokens: string[],
  current: string,
  previousToken: string
): string[] | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  const found = findCompletionMetadata(tokens);
  if (!found) {
    return null;
  }

  const { metadata, positionalIndex } = found;

  // Flag dispatch has precedence over positional dispatch.
  if (previousToken && isFlag(previousToken)) {
    const handler = findFlagCompletion(metadata, previousToken);
    if (handler) {
      return handler(current, tokens);
    }
    // A flag with no registered handler does not fall through to positionals.
    return [];
  }

  const positionals = metadata.positionals ?? [];
  if (positionalIndex >= positionals.length) {
    return null;
  }

  const positional = positionals[positionalIndex];
  if (positional.complete) {
    return positional.complete(current, tokens);
  }
  if (positional.choices) {
    return positional.choices.filter((choice) => choice.startsWith(current));
  }
  return [];
}
