import { yargsGraphCommand } from '../graph/command-object';
import { yargsRunManyCommand } from '../run-many/command-object';
import { yargsRunCommand } from '../run/command-object';
import { yargsWatchCommand } from '../watch/command-object';

export interface NxCommandHandler {
  builder?: (yargs: Argv) => Argv;
}

/**
 * Returns a map from command name to its yargs handler object (which includes
 * a `builder` function). Used to introspect which options each command
 * declares so that completion aliases stay in sync with the CLI.
 */
export function getNxCommandHandlers(): Record<string, NxCommandHandler> {
  return {
    run: yargsRunCommand as NxCommandHandler,
    'run-many': yargsRunManyCommand as NxCommandHandler,
    affected: yargsAffectedCommand as NxCommandHandler,
    graph: yargsGraphCommand as NxCommandHandler,
    watch: yargsWatchCommand as NxCommandHandler,
    generate: yargsGenerateCommand as NxCommandHandler,
  };
}

/**
 * Runs a yargs builder function against a throwaway yargs instance and extracts
 * its option alias groups. Returns an object whose `aliases` Map maps each
 * canonical option name to the array of yargs-declared aliases for that option.
 * Returns null on failure.
 */
export function introspectBuilder(
  builder: (yargs: Argv) => Argv
): { aliases: Map<string, string[]> } | null {
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const yargsFactory = require('yargs');
    const instance = yargsFactory([]);
    const result = builder(instance);
    const options = (result as any).getOptions();
    const aliasGroups: Record<string, string[]> = options?.alias ?? {};

    const aliases = new Map<string, string[]>();
    for (const [canonical, aliasList] of Object.entries(aliasGroups)) {
      aliases.set(canonical, Array.isArray(aliasList) ? aliasList : []);
    }

    return { aliases };
  } catch {
    return null;
  }
}
