function getAddPackageCompletions(current: string): string[] {
  try {
    // packages/nx/src/command-line/completion -> packages/nx/package.json
    const pkg = readJsonFile(join(__dirname, '../../../package.json'));
    const packageGroup: Array<string | { package: string }> =
      pkg['nx-migrations']?.packageGroup ?? [];
    return packageGroup
