const BEGIN = '###-begin-nx-completions-###';
const END = '###-end-nx-completions-###';

function bashScript(): string {
  return `${BEGIN}
#
# nx bash completion
#
# Installs a completion function for the \`nx\` command. On <TAB>, it locates the
# workspace-local nx binary and asks it (via NX_COMPLETE) for completions.
#
_nx_completions() {
  COMPREPLY=()
  local cur="\${COMP_WORDS[COMP_CWORD]}"

  # Walk up from the current directory to find the workspace-local nx binary.
  local dir="$PWD"
  local nx_bin=""
  while [ "$dir" != "/" ]; do
    if [ -x "$dir/node_modules/.bin/nx" ]; then
      nx_bin="$dir/node_modules/.bin/nx"
      break
    fi
    if [ -x "$dir/.nx/installation/node_modules/.bin/nx" ]; then
      nx_bin="$dir/.nx/installation/node_modules/.bin/nx"
      break
    fi
    dir="$(dirname "$dir")"
  done
  if [ -z "$nx_bin" ]; then
    nx_bin="nx"
  fi

  local completions
  completions="$(NX_COMPLETE=bash NX_VERBOSE_LOGGING=false "$nx_bin" "\${COMP_WORDS[@]:1}" 2>/dev/null)"
  COMPREPLY=( $(compgen -W "$completions" -- "$cur") )
  return 0
}
complete -F _nx_completions nx
${END}
`;
}

function zshScript(): string {
  // NOTE: this uses \`compadd -d\` to attach descriptions and deliberately does
  // NOT use \`_describe '\` because completion values may contain colons.
  return `${BEGIN}
#
# nx zsh completion
#
_nx_completions() {
  # Walk up from the current directory to find the workspace-local nx binary.
  local dir="$PWD"
  local nx_bin=""
  while [ "$dir" != "/" ]; do
    if [ -x "$dir/node_modules/.bin/nx" ]; then
      nx_bin="$dir/node_modules/.bin/nx"
      break
    fi
    if [ -x "$dir/.nx/installation/node_modules/.bin/nx" ]; then
      nx_bin="$dir/.nx/installation/node_modules/.bin/nx"
      break
    fi
    dir="$(dirname "$dir")"
  done
  if [ -z "$nx_bin" ]; then
    nx_bin="nx"
  fi

  local -a values
  local -a display
  local line value desc
  while IFS=$'\\t' read -r value desc; do
    [ -z "$value" ] && continue
    values+=("$value")
    if [ -n "$desc" ]; then
      display+=("$value -- $desc")
    else
      display+=("$value")
    fi
  done < <(NX_COMPLETE=zsh NX_VERBOSE_LOGGING=false "$nx_bin" "\${words[@]:1}" 2>/dev/null)

  compadd -d display -a values
}
compdef _nx_completions nx
${END}
`;
}

function fishScript(): string {
  return `${BEGIN}
#
# nx fish completion
#
function __nx_complete
  # Walk up from the current directory to find the workspace-local nx binary.
  set -l dir $PWD
  set -l nx_bin ""
  while test "$dir" != "/"
    if test -x "$dir/node_modules/.bin/nx"
      set nx_bin "$dir/node_modules/.bin/nx"
      break
    end
    if test -x "$dir/.nx/installation/node_modules/.bin/nx"
      set nx_bin "$dir/.nx/installation/node_modules/.bin/nx"
      break
    end
    set dir (dirname "$dir")
  end
  if test -z "$nx_bin"
    set nx_bin nx
  end

  set -l tokens (commandline -opc) (commandline -ct)
  NX_COMPLETE=fish NX_VERBOSE_LOGGING=false $nx_bin $tokens[2..-1] 2>/dev/null
end
complete -c nx -f -a '(__nx_complete)'
${END}
`;
}

function powershellScript(): string {
  return `${BEGIN}
#
# nx PowerShell completion
#
Register-ArgumentCompleter -Native -CommandName nx -ScriptBlock {
  param($wordToComplete, $commandAst, $cursorPosition)

  # Walk up from the current directory to find the workspace-local nx binary.
  $dir = (Get-Location).Path
  $nxBin = $null
  while ($dir) {
    if (Test-Path (Join-Path $dir 'node_modules\\.bin\\nx.cmd')) {
      $nxBin = (Join-Path $dir 'node_modules\\.bin\\nx.cmd')
      break
    }
    if (Test-Path (Join-Path $dir '.nx\\installation\\node_modules\\.bin\\nx.cmd')) {
      $nxBin = (Join-Path $dir '.nx\\installation\\node_modules\\.bin\\nx.cmd')
      break
    }
    $parent = Split-Path $dir -Parent
    if ($parent -eq $dir) { break }
    $dir = $parent
  }
  if (-not $nxBin) { $nxBin = 'nx' }

  $env:NX_COMPLETE = 'powershell'
  $env:NX_VERBOSE_LOGGING = 'false'
  $tokens = @($commandAst.CommandElements | Select-Object -Skip 1 | ForEach-Object { $_.ToString() })
  & $nxBin $tokens 2>$null | ForEach-Object {
    [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
  }
  Remove-Item Env:\\NX_COMPLETE -ErrorAction SilentlyContinue
}
${END}
`;
}

/**
 * Generates a shell completion installation script for the given shell.
 */
export async function generateScript(shell: Shell): Promise<string> {
  switch (shell) {
    case 'bash':
      return bashScript();
    case 'zsh':
      return zshScript();
    case 'fish':
      return fishScript();
    case 'powershell':
      return powershellScript();
    default:
      throw new Error(`Unsupported shell for nx completion: ${shell}`);
  }
}
